from pathlib import Path
p=Path('site/promotion-runtime.js')
s=p.read_text(encoding='utf-8')
old='''export function isActualLithiumBattery(product){if(sectionOf(product)!=="lithium-batteries")return false;const primary=[product?.title,product?.name,product?.category,product?.sku,product?.supplierSku].map(x=>clean(x,1200).toLowerCase()).join(" ");const description=clean(product?.description,3000).toLowerCase();const excluded=/battery\\s*(?:box|case|tray|holder)|power\\s*bank|power\\s*station|charger|charging\\s*cable|\\bcable\\b|adapter|connector|terminal|monitor|meter|accessor/;if(excluded.test(primary))return false;const positive=/\\blifepo4\\b|\\blithium(?:[- ]ion| iron phosphate)?\\b[^.]{0,100}\\bbatter(?:y|ies)\\b|\\bbatter(?:y|ies)\\b[^.]{0,100}\\b(?:12|24|36|48)\\s*v\\b|\\b\\d{2,4}\\s*ah\\b[^.]{0,100}\\bbatter(?:y|ies)\\b/;if(positive.test(primary))return true;return !excluded.test(description.slice(0,500))&&positive.test(description);}'''
new='''export function isActualLithiumBattery(product){if(sectionOf(product)!=="lithium-batteries")return false;const identity=[product?.title,product?.name,product?.sku,product?.supplierSku].map(x=>clean(x,1200).toLowerCase()).join(" ");const description=clean(product?.description,3000).toLowerCase();const category=clean(product?.category,500).toLowerCase();const excluded=/battery\\s*(?:box|case|tray|holder)|power\\s*bank|power\\s*station|\\bcharger\\b|charging\\s*cable|\\bcable\\b|adapter|connector|terminal|monitor|meter|accessor/;const positive=/\\blifepo4\\b|\\blithium(?:[- ]ion| iron phosphate)?\\b[^.]{0,100}\\bbatter(?:y|ies)\\b|\\bbatter(?:y|ies)\\b[^.]{0,100}\\b(?:12|24|36|48)\\s*v\\b|\\b\\d{2,4}\\s*ah\\b[^.]{0,100}\\bbatter(?:y|ies)\\b/;if(excluded.test(identity))return false;if(positive.test(identity))return true;const detail=`${description} ${category}`;return !excluded.test(description.slice(0,500))&&positive.test(detail);}'''
if old not in s: raise RuntimeError('Lithium classifier marker missing')
s=s.replace(old,new,1)
p.write_text(s,encoding='utf-8')
print('Lithium classifier repaired: product identity now takes precedence over broad supplier category labels')
